import java.util.NoSuchElementException;
import java.util.Objects;

/**
 * A single key/value entry stored in the hash table.
 *
 * <p>The key is immutable; the value may be updated in place when an existing
 * key is re-inserted.
 */
final class HashEntry<K, V> {
    final K key;
    V value;

    HashEntry(K key, V value) {
        this.key = key;
        this.value = value;
    }
}

/**
 * A hash map for arbitrary key and value types that resolves collisions by open
 * addressing with linear probing.
 *
 * <p>Keys are located with a spread {@link Object#hashCode} and compared with
 * {@link Object#equals}. Removed slots are marked with a tombstone
 * (distinguished by reference identity, never by a magic value) so that probe
 * sequences passing through a removed entry are not cut short. The table grows
 * automatically once the fraction of occupied slots crosses
 * {@link #MAX_LOAD_FACTOR}, which keeps probe sequences short and guarantees
 * that every probe loop terminates at an empty slot.
 *
 * <p>Null keys are not permitted, since a key must be hashable. Null values
 * <em>are</em> permitted; use {@link #containsKey} to distinguish an absent key
 * from a key mapped to {@code null}.
 *
 * @param <K> the type of keys
 * @param <V> the type of values
 */
class LinearProbingHashMap<K, V> {
    private static final int DEFAULT_CAPACITY = 16;

    /**
     * Linear probing degrades sharply as the table fills, so it is resized well
     * before it is full. This also ensures at least one slot is always empty,
     * which is what makes the probing loops guaranteed to terminate.
     */
    private static final double MAX_LOAD_FACTOR = 0.5;

    /**
     * Sentinel marking a slot whose entry was removed. Held as a raw type so it
     * can mark a slot of any instantiation; it is only ever compared by identity
     * and never inspected, so its null key/value are harmless.
     */
    @SuppressWarnings({"rawtypes", "unchecked"})
    private static final HashEntry TOMBSTONE = new HashEntry(null, null);

    private HashEntry<K, V>[] table;
    private int size; // number of live entries
    private int used; // live entries + tombstones (i.e. non-empty slots)

    public LinearProbingHashMap() {
        this(DEFAULT_CAPACITY);
    }

    public LinearProbingHashMap(int initialCapacity) {
        if (initialCapacity < 1) {
            throw new IllegalArgumentException(
                "initialCapacity must be positive: " + initialCapacity);
        }
        table = newTable(initialCapacity);
    }

    @SuppressWarnings("unchecked")
    private HashEntry<K, V>[] newTable(int capacity) {
        return (HashEntry<K, V>[]) new HashEntry[capacity];
    }

    /** The tombstone, viewed as an entry that can be stored in {@link #table}. */
    @SuppressWarnings("unchecked")
    private HashEntry<K, V> tombstone() {
        return (HashEntry<K, V>) TOMBSTONE;
    }

    private int indexFor(K key) {
        // Spread the high bits into the low bits so that poor hashCodes do not
        // cluster under the modulo, which linear probing is especially sensitive
        // to. floorMod then keeps the index in [0, table.length) even when the
        // hash is negative.
        int h = key.hashCode();
        h ^= (h >>> 16);
        return Math.floorMod(h, table.length);
    }

    /**
     * Inserts the key, or updates the value if the key is already present.
     *
     * @throws NullPointerException if {@code key} is null
     */
    public void put(K key, V value) {
        Objects.requireNonNull(key, "key must not be null");
        if (used + 1 > table.length * MAX_LOAD_FACTOR) {
            resize(table.length * 2);
        }

        int index = indexFor(key);
        int firstTombstone = -1;

        while (table[index] != null) {
            if (table[index] == TOMBSTONE) {
                if (firstTombstone < 0) {
                    firstTombstone = index;
                }
            } else if (table[index].key.equals(key)) {
                table[index].value = value; // update in place
                return;
            }
            index = (index + 1) % table.length;
        }

        // Key is absent. Prefer reusing a tombstone over consuming a fresh slot.
        if (firstTombstone >= 0) {
            table[firstTombstone] = new HashEntry<>(key, value);
        } else {
            table[index] = new HashEntry<>(key, value);
            used++;
        }
        size++;
    }

    /**
     * Returns the value for {@code key}.
     *
     * @throws NoSuchElementException if the key is not present
     */
    public V get(K key) {
        int index = findIndex(key);
        if (index < 0) {
            throw new NoSuchElementException("No mapping for key " + key);
        }
        return table[index].value;
    }

    /** Returns the value for {@code key}, or {@code defaultValue} if absent. */
    public V getOrDefault(K key, V defaultValue) {
        int index = findIndex(key);
        return index < 0 ? defaultValue : table[index].value;
    }

    public boolean containsKey(K key) {
        return findIndex(key) >= 0;
    }

    /**
     * Removes the mapping for {@code key}.
     *
     * @return {@code true} if a mapping was removed, {@code false} if the key
     *         was not present.
     */
    public boolean remove(K key) {
        int index = findIndex(key);
        if (index < 0) {
            return false;
        }
        table[index] = tombstone(); // keep the probe sequence intact
        size--;
        return true;
    }

    /** Returns the index of {@code key}, or {@code -1} if it is not present. */
    private int findIndex(K key) {
        if (key == null) {
            return -1; // null keys are never stored
        }
        int index = indexFor(key);
        // The load factor guarantees an empty slot, so this loop terminates.
        while (table[index] != null) {
            if (table[index] != TOMBSTONE && table[index].key.equals(key)) {
                return index;
            }
            index = (index + 1) % table.length;
        }
        return -1;
    }

    private void resize(int newCapacity) {
        HashEntry<K, V>[] old = table;
        table = newTable(newCapacity);
        size = 0;
        used = 0;
        for (HashEntry<K, V> entry : old) {
            if (entry != null && entry != TOMBSTONE) {
                put(entry.key, entry.value);
            }
        }
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public void display() {
        for (HashEntry<K, V> entry : table) {
            if (entry != null && entry != TOMBSTONE) {
                System.out.println(entry.key + " " + entry.value);
            }
        }
    }

    public static void main(String[] args) {
        LinearProbingHashMap<String, Integer> map = new LinearProbingHashMap<>();
        map.put("one", 1);
        map.put("two", 2);
        map.put("two", 3); // updates the existing key rather than duplicating it
        map.display();
        System.out.println(map.size());
        System.out.println(map.remove("two"));
        System.out.println(map.size());
        System.out.println(map.isEmpty());
        System.out.println(map.containsKey("two"));
    }
}
